import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const disposables = [];

  // Position and orientation from scene specification
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load and cache the background image texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  disposables.push(imageTexture);

  // Create plane geometry matching the atlas region aspect ratio (512:320 = 1.6:1)
  const width = 2.0;
  const height = width / (512 / 320);
  const geometry = new THREE.PlaneGeometry(width, height);
  disposables.push(geometry);

  // Material using Three.js Shading Language (TSL)
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(imageTexture),
  });
  disposables.push(material);

  // Create and add the textured plane mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text overlay via MSDF font atlas
  if (config.textContent) {
    const textMesh = ctx.fontAtlas.render(config.textContent, {
      size: 0.34, // Headline scale from design tokens
      weight: 400,
      font: 'Lora', // Display serif font
      color: config.colors.ink,
      align: 'center',
      anchorX: 'center',
      anchorY: 'middle',
    });
    textMesh.position.z = 0.05;
    group.add(textMesh);
    disposables.push(textMesh);
  }

  // Apply any cinematic primitives from the configuration
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    });
  }

  // Setup event handlers (static element, no interactions)
  group.userData.handlers = {};

  // Resource cleanup
  group.userData.cleanup = () => {
    disposables.forEach((disposable) => {
      if (disposable && typeof disposable.dispose === 'function') {
        disposable.dispose();
      }
    });
    gsap.killTweensOf(group);
  };

  return group;
}
